1	//! Deterministic, graph-owned release roster decisions.
2	//!
3	//! This is deliberately separate from `PublishPlan`: it records the exact
4	//! package/version authority that later intent construction consumes, without
5	//! exposing a mutation route.
6	
7	use callisto_model::{
8	    BumpReason, CommandRunner, CommitSha, Ecosystem, ReleaseDecisionEntry, ReleaseDecisionV1, ReleaseInclusionReason,
9	    ReleasePackageId, Version,
10	};
11	
12	use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};
13	
14	/// Derives the durable roster from a freshly computed version plan.
15	///
16	/// The caller supplies the plan from the same workspace observation; this
17	/// function never inspects `PublishPlan` or a caller-provided release roster.
18	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
19	    workspace: &Workspace<'_, R, D>,
20	    plan: &VersionPlan,
21	) -> Result<ReleaseDecisionV1, GraphError> {
22	    let mut package_ids = std::collections::BTreeMap::new();
23	    for package in workspace.graph.packages() {
24	        let ids = package
25	            .canonical_manifests()
26	            .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
27	            .collect::<Result<Vec<_>, _>>()
28	            .map_err(|_error| GraphError::ReleaseIntentStale)?;
29	        package_ids.insert(package.id.clone(), ids);
30	    }
31	
32	    let mut entries = Vec::new();
33	    for bump in &plan.bumps {
34	        let ids = package_ids.get(&bump.package).ok_or(GraphError::ReleaseIntentStale)?;
35	        for id in ids {
36	            entries.push(ReleaseDecisionEntry {
37	                package: id.clone(),
38	                target_version: bump.to.clone(),
39	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
40	            });
41	        }
42	    }
43	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
44	}
45	
46	/// Derives a durable decision for explicit, exact release identities.
47	///
48	/// A linked group is one release unit: selecting any member includes every
49	/// member of that linked group which the version plan selected. All other
50	/// packages remain outside the authority boundary. The caller must pass
51	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
52	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
53	/// for release authority.
54	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
55	    workspace: &Workspace<'_, R, D>,
56	    plan: &VersionPlan,
57	    selections: &[ReleasePackageId],
58	) -> Result<ReleaseDecisionV1, GraphError> {
59	    let complete = derive_release_decision(workspace, plan)?;
60	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
61	    if selected.len() != selections.len() {
62	        return Err(GraphError::ReleaseIntentStale);
63	    }
64	    if selected
65	        .iter()
66	        .any(|selection| !complete.entries.iter().any(|entry| &entry.package == *selection))
67	    {
68	        return Err(GraphError::ReleaseIntentStale);
69	    }
70	
71	    let linked_groups = complete
72	        .entries
73	        .iter()
74	        .filter(|entry| selected.contains(&entry.package))
75	        .flat_map(|entry| entry.reasons.iter())
76	        .filter_map(|reason| match reason {
77	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
78	            _ => None,
79	        })
80	        .collect::<std::collections::BTreeSet<_>>();
81	
82	    let entries = complete
83	        .entries
84	        .into_iter()
85	        .filter(|entry| {
86	            selected.contains(&entry.package)
87	                || entry.reasons.iter().any(|reason| {
88	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
89	                })
90	        })
91	        .collect();
92	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
93	}
