95	/// Verifies the release roster a merged release commit claims, against a
96	/// release-decision file committed alongside it at `decision_path`.
97	///
98	/// This is intentionally *not* a second computation of changeset, fixed-group,
99	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
100	/// (via [`derive_release_decision`]) already computed that once, correctly,
101	/// when the release PR was generated -- and `callisto version --emit-decision`
102	/// commits its exact output alongside the manifest and changelog edits.
103	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
104	/// the kind of duplicated logic that drifts: an earlier version of this
105	/// function did just that, understood only a direct changeset match, and
106	/// rejected every real release in this repository once a fixed-group cascade
107	/// (a case its reimplementation never learned) touched an unnamed sibling.
108	///
109	/// Instead, this function reads the committed decision back and confirms the
110	/// commit's actual diff matches it exactly -- no more, no less.
111	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
112	/// entries don't match its content digest, so a hand-edited or corrupted
113	/// decision file fails before this function's own diff cross-check runs.
114	///
115	/// The caller must check out the exact merge commit in detached HEAD state
116	/// before creating an intent. GitHub-specific PR/approval provenance belongs
117	/// in the workflow boundary; this graph function verifies the local,
118	/// provider-neutral commit delta only.
119	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
120	    workspace: &Workspace<'_, R, D>,
121	    release_commit: &CommitSha,
122	    decision_path: &std::path::Path,
123	) -> Result<ReleaseDecisionV1, GraphError> {
124	    let head = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "HEAD"])?;
125	    let head = CommitSha::parse(&head).map_err(|_error| GraphError::ReleaseIntentStale)?;
126	    if &head != release_commit {
127	        return Err(GraphError::ReleaseIntentStale);
128	    }
129	
130	    let parent_ref = format!("{}^", release_commit.as_str());
131	    let parent = git_stdout(workspace.runner, &workspace.root, &["rev-parse", &parent_ref])?;
132	    CommitSha::parse(&parent).map_err(|_error| GraphError::ReleaseIntentStale)?;
133	
134	    let changed = git_stdout(
135	        workspace.runner,
136	        &workspace.root,
137	        &[
138	            "diff-tree",
139	            "--no-commit-id",
140	            "--name-status",
141	            "-r",
142	            "--no-renames",
143	            &parent,
144	            release_commit.as_str(),
145	        ],
146	    )?;
147	    let changed = parse_name_status(&changed)?;
148	
149	    // The decision must be freshly authored as part of *this* commit, not a
150	    // stale leftover an earlier release already committed and this one never
151	    // touched -- otherwise a commit that changes nothing real could still
152	    // carry forward a prior, unrelated decision's authority.
153	    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
154	    let decision_freshly_written = changed
155	        .iter()
156	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
157	    if !decision_freshly_written {
158	        return Err(GraphError::ReleaseIntentStale);
159	    }
160	
161	    // A cheap, independent sanity check that this commit is a real version
162	    // application and not just a hand-crafted decision file: some real
163	    // changeset was actually consumed. The decision's own entries, not this
164	    // changeset's content, remain the sole authority verified below.
165	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
166	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
167	    let consumed_a_changeset = changed
168	        .iter()
169	        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
170	    if !consumed_a_changeset {
171	        return Err(GraphError::ReleaseIntentStale);
172	    }
173	
174	    let decision_source = git_file(
175	        workspace.runner,
176	        &workspace.root,
177	        release_commit.as_str(),
178	        &decision_path_str,
179	    )?;
180	    let decision: ReleaseDecisionV1 =
181	        serde_json::from_str(&decision_source).map_err(|_error| GraphError::ReleaseIntentStale)?;
182	    let claimed = decision
183	        .entries
184	        .iter()
185	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
186	        .collect::<std::collections::BTreeMap<_, _>>();
187	
188	    let changed_paths = changed
189	        .iter()
190	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
191	        .collect::<std::collections::BTreeSet<_>>();
192	    let mut observed = std::collections::BTreeSet::new();
193	    for package in workspace.graph.packages() {
194	        let package_ids = package
195	            .canonical_manifests()
196	            .map(|manifest| {
197	                ReleasePackageId::new(manifest.ecosystem(), package.id.name())
198	                    .map_err(|_error| GraphError::ReleaseIntentStale)
199	            })
200	            .collect::<Result<Vec<_>, _>>()?;
201	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
202	        if package_is_claimed {
203	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleaseIntentStale)?;
204	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
205	                return Err(GraphError::ReleaseIntentStale);
206	            }
207	        }
208	        for manifest in package.canonical_manifests() {
209	            let id = ReleasePackageId::new(manifest.ecosystem(), package.id.name())
210	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
211	            let path = manifest.path.to_string_lossy();
212	            let before = manifest_version_at(workspace.runner, &workspace.root, &parent, &path, manifest.ecosystem())?;
213	            let after = manifest_version_at(
214	                workspace.runner,
215	                &workspace.root,
216	                release_commit.as_str(),
217	                &path,
218	                manifest.ecosystem(),
219	            )?;
220	            let changed_version = before != after;
221	            match claimed.get(&id) {
222	                Some(target_version) => {
223	                    if !changed_version || &after != target_version || !changed_paths.contains(path.as_ref()) {
224	                        return Err(GraphError::ReleaseIntentStale);
225	                    }
226	                    observed.insert(id);
227	                }
228	                None => {
229	                    if changed_version {
230	                        // A changed version the committed decision never
231	                        // claimed is not this commit's authority -- fail
232	                        // closed rather than trust a partial match.
233	                        return Err(GraphError::ReleaseIntentStale);
234	                    }
235	                }
236	            }
237	        }
238	    }
239	    if observed.len() != claimed.len() {
240	        return Err(GraphError::ReleaseIntentStale);
241	    }
242	
243	    Ok(decision)
244	}
