246	fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
247	    let output = runner.run("git", args, root)?;
248	    if !output.success() {
249	        return Err(GraphError::ReleaseIntentStale);
250	    }
251	    Ok(output.stdout_trimmed().to_string())
252	}
253	
254	fn parse_name_status(output: &str) -> Result<Vec<(String, String)>, GraphError> {
255	    output
256	        .lines()
257	        .map(|line| {
258	            let (status, path) = line.split_once('\t').ok_or(GraphError::ReleaseIntentStale)?;
259	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
260	                return Err(GraphError::ReleaseIntentStale);
261	            }
262	            Ok((status.to_string(), path.to_string()))
263	        })
264	        .collect()
265	}
266	
267	fn git_file<R: CommandRunner>(
268	    runner: &R,
269	    root: &std::path::Path,
270	    commit: &str,
271	    path: &str,
272	) -> Result<String, GraphError> {
273	    let object = format!("{commit}:{path}");
274	    git_stdout(runner, root, &["show", &object])
275	}
276	
277	fn manifest_version_at<R: CommandRunner>(
278	    runner: &R,
279	    root: &std::path::Path,
280	    commit: &str,
281	    path: &str,
282	    ecosystem: Ecosystem,
283	) -> Result<Version, GraphError> {
284	    let source = git_file(runner, root, commit, path)?;
285	    let format = ecosystem
286	        .canonical_manifest_format()
287	        .ok_or(GraphError::ReleaseIntentStale)?;
288	    // A malformed blob, a version-less manifest (e.g. a Cargo workspace
289	    // root with no [package] table, or a `dynamic = ["version"]` PEP 621
290	    // package), or a Cargo `version.workspace = true` inheritance (which
291	    // `read_identity` deliberately never resolves, having no workspace
292	    // context for a historical git blob) all fail closed here rather than
293	    // panicking or fabricating a version.
294	    let version = callisto_manifests::read_identity(format, &source, std::path::Path::new(path))
295	        .ok()
296	        .and_then(|identity| match identity.version {
297	            Some(callisto_manifests::VersionSource::Literal(v)) => Some(v),
298	            _ => None,
299	        })
300	        .ok_or(GraphError::ReleaseIntentStale)?;
301	    Version::parse(&version, ecosystem.version_grammar()).map_err(|_error| GraphError::ReleaseIntentStale)
302	}
303	
304	fn reason_from_bump(
305	    reason: Option<&BumpReason>,
306	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
307	) -> Result<ReleaseInclusionReason, GraphError> {
308	    match reason {
309	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
310	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
311	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
312	            group_id: group.to_string(),
313	        }),
314	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
315	            Ok(ReleaseInclusionReason::FixedGroup {
316	                group_id: group.to_string(),
317	            })
318	        }
319	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
320	        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
321	            let source = package_ids
322	                .get(via)
323	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
324	                .ok_or(GraphError::ReleaseIntentStale)?;
325	            Ok(ReleaseInclusionReason::Cascade {
326	                from: source,
327	                edge_kind: format!("{dep_kind:?}"),
328	            })
329	        }
330	        Some(BumpReason::PeerEscalation { via, .. }) => {
331	            let source = package_ids
332	                .get(via)
333	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
334	                .ok_or(GraphError::ReleaseIntentStale)?;
335	            Ok(ReleaseInclusionReason::Cascade {
336	                from: source,
337	                edge_kind: "peer".to_string(),
338	            })
339	        }
340	        Some(_) => Err(GraphError::ReleaseIntentStale),
341	    }
342	}
